  archived_at TEXT NOT NULL,
  PRIMARY KEY (archive, id)
);
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','coverlabs',1,'{"updatedAt": "2026-02-11T13:42:51.200Z", "summary": "Custom poster design platform offering powerful creative tools, community discovery, and personal libraries to create, save, and download unique poster designs.", "order": 1, "year": 2025, "description": "Poster creation platform that lets users design fully custom, high-quality posters through an intuitive web-based designer. The experience supports thousands of layout, font, color, and background combinations, along with custom titles, credits, and image uploads. Community-driven discovery allows users to browse, save, edit, and download posters created by others, while a personalized library keeps favorites and works-in-progress organized for easy access and iteration.", "url": "https://www.coverlabs.studio", "hero": "Archive/v1/Projects/coverlabs/coverlabs1.webp", "technology": ["Vuejs", "Tailwind CSS", "Firebase"], "deleted": false, "featured": true, "eyebrow": "Personal", "migration": {"v2ToV1": {"destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "migratedAt": "2026-02-11T13:42:51.088Z", "sourceStoragePrefix": "Archive/v2/", "destCollection": "v1-projects"}}, "title": "Coverlabs", "images": ["Archive/v1/Projects/coverlabs/coverlabs1.webp", "Archive/v1/Projects/coverlabs/coverlabs2.webp", "Archive/v1/Projects/coverlabs/coverlabs3.webp", "Archive/v1/Projects/coverlabs/coverlabs4.webp", "Archive/v1/Projects/coverlabs/coverlabs5.webp"], "id": "coverlabs"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','bluemodus',2,'{"hero": "Archive/v1/Projects/bluemodus/bluemodus_001.webp", "eyebrow": "BlueModus", "featured": true, "deleted": false, "title": "BlueModus", "technology": ["Kentico", "GSAP", "ASP.Net"], "migration": {"v2ToV1": {"sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "destStoragePrefix": "Archive/v1/", "migratedAt": "2026-02-11T13:42:51.088Z", "destCollection": "v1-projects"}}, "order": 2, "updatedAt": "2026-02-11T13:42:51.200Z", "images": ["Archive/v1/Projects/bluemodus/bluemodus_001.webp", "Archive/v1/Projects/bluemodus/bluemodus_002.webp", "Archive/v1/Projects/bluemodus/bluemodus_003.webp", "Archive/v1/Projects/bluemodus/bluemodus_004.webp"], "description": "Agency website showcasing strategy, design, and enterprise technology services for complex digital platforms. The experience balances thought leadership with clear service positioning, case studies, and capability storytelling—supporting lead generation while communicating expertise across CMS implementations, custom development, UX, and ongoing optimization. Content architecture and performance focus help convey credibility, culture, and partnership-driven delivery.", "year": 2023, "url": "https://bluemodus.com/", "summary": "Full-service digital agency delivering strategy, UX/design, and enterprise web development—often centered on CMS platforms, integrations, and long-term support.", "id": "bluemodus"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','ball',3,'{"order": 3, "deleted": false, "description": "Enterprise marketing experience for a global manufacturer focused on sustainable aluminum packaging. The site highlights innovation, recyclability, and environmental commitments through immersive storytelling, motion-driven product and sustainability content, and investor/corporate communications. Structured navigation and rich editorial layouts help audiences explore packaging capabilities, markets served, careers, and long-term ESG goals across a large international footprint.", "eyebrow": "BlueModus", "year": 2021, "images": ["Archive/v1/Projects/ball/ball_001.webp", "Archive/v1/Projects/ball/ball_002.webp", "Archive/v1/Projects/ball/ball_003.webp", "Archive/v1/Projects/ball/ball_004.webp"], "updatedAt": "2026-02-11T13:42:51.200Z", "featured": true, "migration": {"v2ToV1": {"sourceStoragePrefix": "Archive/v2/", "destCollection": "v1-projects", "destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "migratedAt": "2026-02-11T13:42:51.088Z"}}, "url": "http://www.ball.com", "hero": "Archive/v1/Projects/ball/ball_001.webp", "summary": "Global aluminum packaging manufacturer producing recyclable beverage cans and containers, emphasizing sustainability, innovation, and circular-economy goals.", "technology": ["Kentico Experience", "GSAP", "Angular"], "title": "Ball", "id": "ball"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','communityTransit',3,'{"order": 3, "hero": "Archive/v1/Projects/communityTransit/communityTransit_001.webp", "technology": ["React", "Sitefinity", "OpenTripPlanner"], "description": "Public transit experience focused on fast trip planning and rider self-service across local, express, and rapid lines. The site brings together real-time service alerts, schedules, route maps, fare information, and accessibility resources with clear IA and search. Riders can plan trips, review station/stop details, and explore options like vanpools, on-demand shuttles, and paratransit—optimized for mobile use on the go.", "images": ["Archive/v1/Projects/communityTransit/communityTransit_001.webp", "Archive/v1/Projects/communityTransit/communityTransit_002.webp", "Archive/v1/Projects/communityTransit/communityTransit_003.webp", "Archive/v1/Projects/communityTransit/communityTransit_004.webp"], "eyebrow": "BlueModus", "updatedAt": "2026-02-11T13:42:51.200Z", "deleted": false, "migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "destCollection": "v1-projects", "destStoragePrefix": "Archive/v1/"}}, "summary": "Regional transit provider offering bus and rapid services plus vanpool and paratransit, with tools for trip planning, fares, schedules, maps, and alerts.", "featured": false, "year": 2025, "url": "https://www.communitytransit.org/", "title": "Community Transit", "id": "communityTransit"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','rasi',4,'{"description": "Service site for a nationwide registered agent and corporate compliance provider, built to communicate coverage, reliability, and technology-enabled workflows. The experience supports businesses that need statutory representation and document handling across jurisdictions, presenting offerings like registered agent service, compliance tools, and entity support. Clear navigation and conversion flows help organizations evaluate services, request help, and manage ongoing obligations efficiently.", "migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "destStoragePrefix": "Archive/v1/", "destCollection": "v1-projects"}}, "order": 4, "hero": "Archive/v1/Projects/rasi/rasi_001.webp", "summary": "Registered agent and corporate compliance provider with nationwide coverage, helping businesses manage statutory representation, filings, and ongoing compliance needs.", "images": ["Archive/v1/Projects/rasi/rasi_001.webp", "Archive/v1/Projects/rasi/rasi_002.webp", "Archive/v1/Projects/rasi/rasi_003.webp"], "url": "https://www.rasi.com/", "deleted": false, "eyebrow": "BlueModus", "featured": false, "technology": ["Kentico", "Vue.js"], "year": 2024, "updatedAt": "2026-02-11T13:42:51.200Z", "title": "Registered Agent Solutions, Inc", "id": "rasi"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','ads',5,'{"url": "https://www.adsinterlock.com", "technology": ["Kentico", ".Net Framework", "Vue.js"], "deleted": false, "order": 5, "migration": {"v2ToV1": {"destStoragePrefix": "Archive/v1/", "sourceStoragePrefix": "Archive/v2/", "destCollection": "v1-projects", "sourceCollection": "v2-projects", "migratedAt": "2026-02-11T13:42:51.088Z"}}, "year": 2023, "eyebrow": "BlueModus", "updatedAt": "2026-02-11T13:42:51.200Z", "summary": "Ignition interlock provider helping DUI-offense compliance across many states by preventing vehicle ignition when alcohol is detected and enabling monitoring/reporting.", "description": "National provider of court-mandated ignition interlock solutions that help reduce impaired driving by requiring a breath sample before a vehicle can start. The experience supports users, service locations, and monitoring needs with clear onboarding, device guidance, appointment/location flows, compliance education, and secure reporting tools for agencies—optimized for fast access on mobile and desktop.", "hero": "Archive/v1/Projects/ads/ads_001.webp", "featured": false, "title": "Alcohol Detection Systems", "images": ["Archive/v1/Projects/ads/ads_001.webp", "Archive/v1/Projects/ads/ads_002.webp", "Archive/v1/Projects/ads/ads_003.webp", "Archive/v1/Projects/ads/ads_004.webp"], "id": "ads"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','flow',6,'{"eyebrow": "BlueModus", "year": 2023, "deleted": false, "technology": ["Kentico", "jQuery", "Swiper", "Azure"], "migration": {"v2ToV1": {"sourceCollection": "v2-projects", "destCollection": "v1-projects", "sourceStoragePrefix": "Archive/v2/", "destStoragePrefix": "Archive/v1/", "migratedAt": "2026-02-11T13:42:51.088Z"}}, "order": 6, "title": "Flow", "images": ["Archive/v1/Projects/flow/flow_001.webp", "Archive/v1/Projects/flow/flow_002.webp", "Archive/v1/Projects/flow/flow_003.webp"], "description": "Manufacturer site presenting ultrahigh-pressure abrasive waterjet cutting systems for industrial applications. The experience explains technology benefits—precision cutting without heat distortion—while guiding visitors through machines, materials, industries served, and support resources. Strong editorial structure and product storytelling help engineers and buyers evaluate capabilities, configurations, and service options, supported by clear calls to request demos and quotes.", "updatedAt": "2026-02-11T13:42:51.200Z", "hero": "Archive/v1/Projects/flow/flow_001.webp", "featured": false, "url": "https://www.flowwaterjet.com/", "summary": "Industrial waterjet cutting manufacturer delivering ultrahigh-pressure systems for precise, cold cutting of metals, stone, glass, composites, and more.", "id": "flow"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','lexitaslegal',7,'{"technology": ["Kentico", ".Net Framework"], "featured": false, "summary": "Legal support services provider offering nationwide solutions for law firms—helping manage workflows and deliver reliable operational support across cases and practices.", "title": "Lexitas Legal", "migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "destCollection": "v1-projects", "sourceStoragePrefix": "Archive/v2/"}}, "description": "Professional services website for legal support offerings, designed to help firms quickly understand capabilities and request help. The experience focuses on clarity and credibility, organizing services, coverage, and differentiators into scannable pages supported by streamlined conversion paths. Content structure supports multiple audiences—attorneys, operations teams, and partners—while reinforcing reliability, responsiveness, and nationwide service delivery across litigation support needs.", "hero": "Archive/v1/Projects/lexitas/lexitas_001.webp", "url": "https://www.lexitaslegal.com/", "updatedAt": "2026-02-11T13:42:51.200Z", "images": ["Archive/v1/Projects/lexitas/lexitas_001.webp", "Archive/v1/Projects/lexitas/lexitas_002.webp", "Archive/v1/Projects/lexitas/lexitas_003.webp"], "year": 2022, "order": 7, "eyebrow": "BlueModus", "deleted": false, "id": "lexitaslegal"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','broan',8,'{"description": "Product-forward experience for premium kitchen ventilation, designed to help homeowners and designers choose the right hood by style, size, and performance. The site emphasizes strong visuals, comparison-ready product detail pages, specs and installation resources, and inspiration content that bridges function and aesthetics. Modern front-end interactions support browsing, filtering, and exploration across collections and finishes.", "order": 8, "hero": "Archive/v1/Projects/broan/boran_001.webp", "summary": "High-performance kitchen ventilation brand offering range hoods across styles and sizes, combining effective air capture with design-forward materials and finishes.", "updatedAt": "2026-02-11T13:42:51.200Z", "images": ["Archive/v1/Projects/broan/boran_001.webp", "Archive/v1/Projects/broan/broan_002.webp", "Archive/v1/Projects/broan/broan_003.webp", "Archive/v1/Projects/broan/broan_004.webp"], "url": "https://bestrangehoods.com/", "deleted": false, "eyebrow": "BlueModus", "migration": {"v2ToV1": {"sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "destStoragePrefix": "Archive/v1/", "destCollection": "v1-projects", "migratedAt": "2026-02-11T13:42:51.088Z"}}, "featured": false, "year": 2021, "title": "Broan Best Range Hoods", "technology": ["Umbraco", "Next.js", "React", "Swiper"], "id": "broan"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','opsdt',9,'{"migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "destStoragePrefix": "Archive/v1/", "sourceStoragePrefix": "Archive/v2/", "destCollection": "v1-projects", "sourceCollection": "v2-projects"}}, "eyebrow": "BlueModus", "order": 9, "images": ["Archive/v1/Projects/opsdt/opsdt_001.webp", "Archive/v1/Projects/opsdt/opsdt_002.webp", "Archive/v1/Projects/opsdt/opsdt_003.webp"], "deleted": false, "year": 2021, "description": "Public-facing information hub for an independent discipline tribunal, designed to support transparency and access to proceedings. The experience organizes mandates, processes, hearing information, decisions, and resources in a clear, trial-like framework while remaining approachable for the public. Strong IA and searchability help users find governance details, procedures, and published outcomes, reinforcing impartiality and trust in adjudication.", "technology": ["Kentico", "jQuery"], "featured": false, "hero": "Archive/v1/Projects/opsdt/opsdt_001.webp", "url": "https://opsdt.ca/", "updatedAt": "2026-02-11T13:42:51.200Z", "summary": "Independent tribunal that adjudicates physician discipline matters, publishing processes and decisions to support transparency, fairness, and public access to outcomes.", "title": "OPSDT", "id": "opsdt"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','premiummedia360',10,'{"migration": {"v2ToV1": {"destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "migratedAt": "2026-02-11T13:42:51.088Z", "destCollection": "v1-projects", "sourceStoragePrefix": "Archive/v2/"}}, "eyebrow": "Premium Data 360", "deleted": false, "order": 10, "hero": "Archive/v1/Projects/premiummedia360/premiummedia360_001.webp", "featured": false, "images": ["Archive/v1/Projects/premiummedia360/premiummedia360_001.webp", "Archive/v1/Projects/premiummedia360/premiummedia360_002.webp", "Archive/v1/Projects/premiummedia360/premiummedia360_003.webp", "Archive/v1/Projects/premiummedia360/premiummedia360_004.webp", "Archive/v1/Projects/premiummedia360/premiummedia360_005.webp", "Archive/v1/Projects/premiummedia360/premiummedia360_006.webp"], "title": "GIACloud", "technology": ["Vue.js", "DevExtreme", "ASP.NET", "MSSQL"], "summary": "Automation platform that streamlines PO-to-invoice reconciliation and data sharing for media/tech partners, reducing manual work, errors, and operational waste.", "url": "https://www.premiumdata360.com/", "year": 2020, "description": "Web experience for a plug-and-play reconciliation platform that automates data sharing from purchase order through invoice for media and technology partners. The product messaging emphasizes removing manual spreadsheet work, reducing discrepancies, and improving operational efficiency through standardized workflows and automated matching. Built to communicate value quickly, the site supports understanding of capabilities, integrations, and outcomes for finance and operations teams.", "updatedAt": "2026-02-11T13:42:51.200Z", "id": "premiummedia360"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','sandbar',11,'{"year": 2019, "url": "", "title": "Sandbar", "description": "Modular internal web application suite built to improve productivity and sales through purpose-driven tools. The system combines front-end and back-end development with UX/UI design, database structure, and server setup, supporting multiple apps under one cohesive platform. Contributions spanned conception, wireframes, branding, data modeling, and ongoing enhancements enabling teams to track work, manage operations, and streamline workflows over time.", "technology": ["SPA", "Vue.js", "Socket.io", "Ubuntu", "MSSQL", "Crystal Reports"], "summary": "Modular internal web app suite that improved operational efficiency and sales via multiple interconnected tools, with full-stack buildout, UX, data design, and maintenance.", "updatedAt": "2026-02-11T13:42:51.200Z", "hero": "Archive/v1/Projects/sandbar/sandbar_001_main_001.webp", "eyebrow": "Hemisphere Design Works", "order": 11, "migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "sourceCollection": "v2-projects", "sourceStoragePrefix": "Archive/v2/", "destCollection": "v1-projects", "destStoragePrefix": "Archive/v1/"}}, "images": ["Archive/v1/Projects/sandbar/sandbar_001_main_001.webp", "Archive/v1/Projects/sandbar/sandbar_002_main_002.webp", "Archive/v1/Projects/sandbar/sandbar_003_main_003.webp", "Archive/v1/Projects/sandbar/sandbar_004_main_004.webp", "Archive/v1/Projects/sandbar/sandbar_005_main_005.webp", "Archive/v1/Projects/sandbar/sandbar_007_tracking_001.gif", "Archive/v1/Projects/sandbar/sandbar_008_tracking_002.gif", "Archive/v1/Projects/sandbar/sandbar_009_tracking_003.webp", "Archive/v1/Projects/sandbar/sandbar_010_schedule_001.gif", "Archive/v1/Projects/sandbar/sandbar_011_schedule_002.gif", "Archive/v1/Projects/sandbar/sandbar_012_schedule_003.gif", "Archive/v1/Projects/sandbar/sandbar_013_mro_001.gif", "Archive/v1/Projects/sandbar/sandbar_014_mro_002.gif", "Archive/v1/Projects/sandbar/sandbar_015_mro_003.gif", "Archive/v1/Projects/sandbar/sandbar_016_mro_004.webp", "Archive/v1/Projects/sandbar/sandbar_017_ecr_001.gif", "Archive/v1/Projects/sandbar/sandbar_018_ecr_002.gif", "Archive/v1/Projects/sandbar/sandbar_019_ecr_003.gif", "Archive/v1/Projects/sandbar/sandbar_021_operations_001.webp", "Archive/v1/Projects/sandbar/sandbar_022_operations_002.webp", "Archive/v1/Projects/sandbar/sandbar_023_operations_003.gif", "Archive/v1/Projects/sandbar/sandbar_024_expenditures_001.gif", "Archive/v1/Projects/sandbar/sandbar_025_expenditures_002.webp"], "deleted": false, "featured": true, "id": "sandbar"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','harbor',12,'{"year": 2017, "description": "Factory-floor companion app built for minimal interaction and controlled access, allowing line leaders and employees to submit real-time task updates without exposing unnecessary functions. The UI restricts actions to permitted workflows, reducing mistakes and speeding adoption on the floor. Designed to deploy multiple variations from a single codebase, it pairs with a broader operations suite to keep production status visible and current.", "images": ["Archive/v1/Projects/harbor/harbor_001.webp", "Archive/v1/Projects/harbor/harbor_002.webp", "Archive/v1/Projects/harbor/harbor_003.webp", "Archive/v1/Projects/harbor/harbor_004.gif", "Archive/v1/Projects/harbor/harbor_005.webp"], "featured": false, "summary": "Restricted-action factory app for capturing real-time production/task updates from the floor, designed for quick use, low error rates, and flexible deployment.", "title": "Harbor", "migration": {"v2ToV1": {"sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "migratedAt": "2026-02-11T13:42:51.088Z", "destStoragePrefix": "Archive/v1/", "destCollection": "v1-projects"}}, "url": "", "order": 12, "technology": ["C#", "WPF Forms", "MSSQL", "Crystal Reports"], "updatedAt": "2026-02-11T13:42:51.200Z", "eyebrow": "Hemisphere Design Works", "hero": "Archive/v1/Projects/harbor/harbor_001.webp", "deleted": false, "id": "harbor"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','lighthouse',13,'{"featured": false, "deleted": false, "title": "Lighthouse", "eyebrow": "Hemisphere Design Works", "updatedAt": "2026-02-11T13:42:51.200Z", "year": 2018, "description": "Personal utility application built to simplify daily procedures and speed up recurring tasks for individual users. The platform supports ongoing expansion, with features organized into sections that are permission-gated so people only see what’s relevant. A focus on straightforward navigation, quick actions, and scalable structure makes it easy to add new modules over time while maintaining security, role clarity, and a consistent user experience.", "hero": "Archive/v1/Projects/lighthouse/lighthouse_001.webp", "technology": ["C#", "WPF Forms", "MSSQL", "Crystal Reports"], "migration": {"v2ToV1": {"destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "sourceStoragePrefix": "Archive/v2/", "migratedAt": "2026-02-11T13:42:51.088Z", "destCollection": "v1-projects"}}, "summary": "Permission-based utility app that streamlines day-to-day workflows for individuals, designed to scale through modular sections while keeping access tightly controlled.", "order": 13, "images": ["Archive/v1/Projects/lighthouse/lighthouse_001.webp", "Archive/v1/Projects/lighthouse/lighthouse_002.webp", "Archive/v1/Projects/lighthouse/lighthouse_003.gif"], "url": "", "id": "lighthouse"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','johnstonboilercomapny',14,'{"images": ["Archive/v1/Projects/johnstonboiler/johnstonboilercompany_001.webp", "Archive/v1/Projects/johnstonboiler/johnstonboilercompany_002.webp", "Archive/v1/Projects/johnstonboiler/johnstonboilercompany_003.webp"], "year": 2014, "eyebrow": "Johnston Boiler Company", "updatedAt": "2026-02-11T13:42:51.200Z", "title": "Sales Assistant", "deleted": false, "hero": "Archive/v1/Projects/johnstonboiler/johnstonboilercompany_001.webp", "order": 14, "migration": {"v2ToV1": {"sourceCollection": "v2-projects", "destStoragePrefix": "Archive/v1/", "destCollection": "v1-projects", "migratedAt": "2026-02-11T13:42:51.088Z", "sourceStoragePrefix": "Archive/v2/"}}, "summary": "Desktop sales assistant that turns Excel pricing data into guided, error-resistant quote generation with dynamic option filtering and consistent outputs.", "featured": false, "description": "Desktop quoting tool that integrates with Excel-based price books to generate accurate quotes for specialized orders. The application uses dynamic filtering so only valid options appear based on prior selections, reducing errors and speeding the sales workflow. Built to support repeatable quote creation, consistent formatting, and easier maintenance of pricing logic while keeping the interface efficient for daily use by sales staff.", "url": "", "technology": ["C#", "WPF Forms", "Excel"], "id": "johnstonboilercomapny"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','lhfs',16,'{"migration": {"v2ToV1": {"migratedAt": "2026-02-11T13:42:51.088Z", "destStoragePrefix": "Archive/v1/", "sourceCollection": "v2-projects", "destCollection": "v1-projects", "sourceStoragePrefix": "Archive/v2/"}}, "order": 16, "url": "https://www.lhfs.com/", "images": ["Archive/v1/Projects/lhfs/lhfs_001.webp", "Archive/v1/Projects/lhfs/lhfs_002.webp", "Archive/v1/Projects/lhfs/lhfs_003.webp"], "description": "Nationwide mortgage lender offering personalized home financing solutions across a broad range of loan types, including conventional, FHA, VA, USDA, and manufactured home programs. The platform guides borrowers with transparent communication, expert loan advice, and tailored lending options through every stage of buying, refinancing, or building a home. Resources include a knowledge center, payment tools, and community-focused lending programs that support first-time buyers, down payment assista", "hero": "Archive/v1/Projects/lhfs/lhfs_001.webp", "featured": false, "summary": "Mortgage lending service providing tailored home loans, refinancing options, and expert guidance with nationwide coverage and community-focused support.", "eyebrow": "Third Coast Creative", "technology": ["Blazor", "Tailwind CSS", ".Net"], "deleted": false, "updatedAt": "2026-02-11T13:42:51.200Z", "year": 2025, "title": "Land Home Financial Services", "id": "lhfs"}','2026-10-09T00:00:00Z');
INSERT OR REPLACE INTO archive_projects (archive,id,sort_order,data_json,archived_at) VALUES ('v1','iada',17,'{"summary": "Trade association site advocating for Illinois franchised auto dealers with resources, legislative advocacy, licensing guidance, and industry support.", "technology": ["Wordpress", "PHP", "GravityForms"], "hero": "Archive/v1/Projects/iada/iada_001.webp", "updatedAt": "2026-02-11T13:42:51.200Z", "title": "Illinois Automobile Dealers Association", "order": 17, "url": "https://www.illinoisdealers.com/", "migration": {"v2ToV1": {"destCollection": "v1-projects", "migratedAt": "2026-02-11T13:42:51.088Z", "sourceStoragePrefix": "Archive/v2/", "sourceCollection": "v2-projects", "destStoragePrefix": "Archive/v1/"}}, "deleted": false, "featured": false, "eyebrow": "Third Coast Creative", "images": ["Archive/v1/Projects/iada/iada_001.webp", "Archive/v1/Projects/iada/iada_002.webp", "Archive/v1/Projects/iada/iada_003.webp", "Archive/v1/Projects/iada/iada_004.webp"], "year": 2024, "description": "Statewide association site representing franchised automobile dealers in Illinois, offering advocacy, resources, and member services to support the retail auto industry. The platform provides legislative updates, dealer licensing info, regulatory guidance, downloadable forms, and industry publications, helping dealerships navigate compliance, title and registration requirements, advertising and tax procedures, and other operational challenges while promoting a favorable business climate.", "id": "iada"}','2026-10-09T00:00:00Z');
